import type { Repo, DocHandle } from "@automerge/automerge-repo/slim";
import type {
  DocLink,
  FolderDoc,
  HasPatchworkMetadata,
  UnixFileEntry,
} from "@inkandswitch/patchwork-filesystem";
import type { Landed } from "../dnd/operations.ts";
import { log } from "../dnd/debug.ts";
import { docLinkFromUrl } from "../lib/doc-link.ts";
import { archiveFor, loadArchive } from "../knit-archives.ts";

/**
 * Turn a file from the operating system into a document: an archive (see
 * knit-archives.ts) is unpacked and gives the doc it was made from, anything
 * else becomes a UnixFileEntry.
 */
export async function fileDocLink(file: File, repo: Repo): Promise<DocLink> {
  const archive = archiveFor(file.name);
  if (archive) {
    const url = await (await loadArchive(archive.id)).import(repo, file);
    log("FileDrop: Unpacked archive:", file.name, url);
    return docLinkFromUrl(repo, url);
  }

  const content = new Uint8Array(await file.arrayBuffer());

  const nameParts = file.name.split(".");
  const extension = nameParts.length > 1 ? nameParts.pop()! : "";
  const nameWithoutExt = nameParts.join(".");

  const handle = await repo.create2<UnixFileEntry & HasPatchworkMetadata>({
    "@patchwork": {
      type: "file",
    },
    content,
    extension,
    mimeType: file.type || "application/octet-stream",
    name: nameWithoutExt,
  });

  log("FileDrop: Created file document:", file.name, handle.url);
  return { url: handle.url, name: file.name, type: "file" };
}

/**
 * fileDocLink for each of `files`, in order. A file that can't be read is
 * skipped and named in `failed`; the rest still go in.
 */
export async function fileDocLinks(
  files: Iterable<File>,
  repo: Repo
): Promise<{ links: DocLink[]; failed: string[] }> {
  const all = [...files];
  const results = await Promise.allSettled(
    all.map((file) => fileDocLink(file, repo))
  );
  results.forEach((result, i) => {
    if (result.status === "rejected") {
      log("FileDrop: Failed to create file document:", all[i].name, result.reason);
    }
  });
  return {
    links: results.flatMap((result) =>
      result.status === "fulfilled" ? [result.value] : []
    ),
    failed: all
      .filter((_, i) => results[i].status === "rejected")
      .map((file) => file.name),
  };
}

/**
 * Bring files picked from the computer into patchwork (see fileDocLink),
 * saying which couldn't be.
 */
export async function localFileDocLinks(
  repo: Repo,
  files: File[]
): Promise<DocLink[]> {
  const { links, failed } = await fileDocLinks(files, repo);
  if (failed.length) alert(`Couldn't add ${failed.join(", ")}.`);
  return links;
}

/**
 * Ask for files from the computer. Resolves with none if the picker is
 * cancelled. Has to be called while handling a click or key press.
 */
export function pickFiles(): Promise<File[]> {
  return new Promise((resolve) => {
    const input = document.createElement("input");
    input.type = "file";
    input.multiple = true;
    input.hidden = true;
    const done = () => {
      resolve([...(input.files ?? [])]);
      input.remove();
    };
    input.addEventListener("change", done);
    input.addEventListener("cancel", done);
    document.body.append(input);
    input.click();
  });
}

/**
 * Turn files dropped from the operating system into documents (see
 * fileDocLink) and insert them into `folderHandle` at `index`, in the order
 * they were dropped. A file that can't be read is skipped and named in
 * `failed`; the rest still go in.
 */
export async function handleFilesDrop(
  files: Iterable<File>,
  folderHandle: DocHandle<FolderDoc>,
  repo: Repo,
  index: number
): Promise<{ landed: Landed[]; failed: string[] }> {
  const { links, failed } = await fileDocLinks(files, repo);
  const insertAt = Math.min(index, folderHandle.doc()?.docs?.length ?? 0);
  folderHandle.change((folder) => {
    folder.docs.splice(insertAt, 0, ...links);
  });
  const landed = links.map((link, i) => ({
    folderUrl: folderHandle.url,
    index: insertAt + i,
    url: link.url,
  }));
  return { landed, failed };
}
